import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.parsing import parse_span
from hourglass.models import Shift


def shift(worker, span="09:00-13:00"):
    return Shift(worker, "mon", parse_span(span))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = timesheet_lines([
            shift("ann", "09:00-10:30"),
            shift("bob", "09:00-17:00"),
            shift("ann", "11:00-12:00")
        ])
        self.assertEqual(lines, [
            "bob: 1 shifts, 8.0 hours",
            "ann: 2 shifts, 2.5 hours"
        ])

    def test_empty_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([shift("  ")])
